const PREFIX='korea-ride-day-updates-v1-';
const topic=(trip:string)=>'https://ntfy.sh/korea-ride-'+trip.replace(/[^a-zA-Z0-9_-]/g,'')+'-c721a9b4';
export function readShared(trip:string){try{return JSON.parse(localStorage.getItem(PREFIX+trip)||'{}')}catch{return {}}}
export function acceptShared(trip:string,msg:any){if(msg?.event!=='message')return false;try{const v=JSON.parse(msg.message);if(v.type!=='korea_day'||v.trip!==trip||typeof v.day!=='string'||!v.value||typeof v.value.title!=='string'||typeof v.value.notes!=='string'||v.value.title.length>180||v.value.notes.length>800||!Number.isFinite(msg.time))return false;const all=readShared(trip);if((all[v.day]?.time||0)>msg.time)return false;all[v.day]={...v.value,time:msg.time,id:msg.id};localStorage.setItem(PREFIX+trip,JSON.stringify(all));return true;}catch{return false;}}
export async function pullShared(trip:string){const r=await fetch(topic(trip)+'/json?poll=1&since=all',{signal:AbortSignal.timeout(12000),cache:'no-store'});if(!r.ok)throw Error('Shared updates unavailable');for(const line of (await r.text()).split('\n')){try{acceptShared(trip,JSON.parse(line));}catch{}}return readShared(trip);}
export async function publishShared(trip:string,day:string,value:{title:string,notes:string}){const r=await fetch(topic(trip),{method:'POST',body:JSON.stringify({type:'korea_day',trip,day,value}),signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('Group delivery failed');const msg=await r.json();if(!acceptShared(trip,msg))throw Error('Group delivery could not be confirmed');return readShared(trip);}
export function watchShared(trip:string,update:()=>void){const stream=new EventSource(topic(trip)+'/sse?since=all');stream.onmessage=e=>{try{if(acceptShared(trip,JSON.parse(e.data)))update();}catch{}};return()=>stream.close();}

lib/local.ts:
const KEY='korea-ride-records-v1';
export function readRecords(){const text=localStorage.getItem(KEY);if(!text)return {};const value=JSON.parse(text);if(!value||typeof value!=='object'||Array.isArray(value))throw new Error('Saved records could not be read. Export a backup before clearing browser data.');return value;}
export function writeRecord(key:string,value:any){const next={...readRecords(),[key]:value};localStorage.setItem(KEY,JSON.stringify(next));return next;}
import type {Day} from './trip';
export async function weatherFor(day:Day){
const today=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Seoul'}));const todayDate=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');
 const ahead=Math.round((Date.parse(day.date)-Date.parse(todayDate))/86400000);
 if(ahead>15||ahead<0)return ({status:ahead<0?'past':'outside',message:ahead<0?'This ride date has passed.':'Ride-day forecast opens about 15 days before departure.',availableFrom:new Date(Date.parse(day.date)-15*86400000).toISOString().slice(0,10)});
 try{const locations=await Promise.all(day.points.slice(0,3).map(async(p,i)=>{const url=new URL('https://api.open-meteo.com/v1/forecast');Object.entries({latitude:String(p[0]),longitude:String(p[1]),hourly:'temperature_2m,precipitation_probability,wind_speed_10m,wind_gusts_10m,wind_direction_10m',daily:'sunrise,sunset',timezone:'Asia/Seoul',start_date:day.date,end_date:day.date}).forEach(([k,v])=>url.searchParams.set(k,v));const r=await fetch(url,{signal:AbortSignal.timeout(12000)});if(!r.ok)throw new Error('Forecast request failed');const j:any=await r.json();return {name:day.places[i],sunrise:j.daily.sunrise[0],sunset:j.daily.sunset[0],hours:[8,11,14,17].map(h=>({hour:h,temp:j.hourly.temperature_2m[h],rain:j.hourly.precipitation_probability[h],wind:j.hourly.wind_speed_10m[h],gust:j.hourly.wind_gusts_10m[h],direction:j.hourly.wind_direction_10m[h]}))};}));return ({status:'available',locations,updatedAt:new Date().toISOString()});}catch(e){console.error(e);return ({status:'error',message:'Weather is temporarily unavailable. Please retry.'});}
}

import {distance} from '@/lib/geo';
import {checkpoints} from '@/lib/trip';
export async function nearbyPlaces(lat:number,lon:number,kind='checkpoints'){
 const radius=kind==='checkpoints'?200000:2000;
 const filter=kind==='checkpoints'?'["name"~"인증센터|인증 센터|certification cent|stamp booth",i]':kind==='food'?'["amenity"~"restaurant|fast_food"]':kind==='snacks'?'["shop"~"convenience|supermarket"]':kind==='repair'?'["shop"="bicycle"]':'["amenity"="cafe"]';
 const query=`[out:json][timeout:25];nwr(around:${radius},${lat},${lon})${filter};out center tags 350;`;
 try{const r=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',body:new URLSearchParams({data:query}),signal:AbortSignal.timeout(29000)});if(!r.ok)throw new Error('Place lookup unavailable');const j:any=await r.json();if(j.remark)throw new Error('Incomplete map response');
 const results=(j.elements||[]).map((e:any)=>{const point=[e.lat??e.center?.lat,e.lon??e.center?.lon];const ko=e.tags?.name||'',en=e.tags?.['name:en'];const match=checkpoints.find(c=>ko.replace(/\s/g,'').includes(c.ko.replace(/\s/g,'')));return {id:match?.id||`osm-${e.type}-${e.id}`,name:match?.name||en||ko||kind,ko,point,km:distance([lat,lon],point),route:match?.route||'Unassigned',day:match?.day||'extra',hours:e.tags?.opening_hours||'',osm:`https://www.openstreetmap.org/${e.type}/${e.id}`};}).filter((e:any)=>e.point.every(Number.isFinite)&&e.km<=radius/1000).sort((a:any,b:any)=>a.km-b.km);
 const unique=Array.from(new Map(results.map((r:any)=>[r.id,r])).values());return ({results:unique,source:'OpenStreetMap contributors',updatedAt:new Date().toISOString()});
 }catch(e){console.error(e);throw new Error('Live map search unavailable');}
}

