type RecordMap=Record<string,any>;
type CP={id:string,name:string,ko:string,route:string,day:string,point?:number[],km?:number,osm?:string,hours?:string};
function Picker({value,onChange,options,label}:{value:string,onChange:(v:string)=>void,options:{value:string,label:string}[],label:string}){return <Select value={value} onValueChange={onChange}><SelectTrigger aria-label={label} className="picker"><SelectValue placeholder={label}/></SelectTrigger><SelectContent>{options.map(o=><SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>)}</SelectContent></Select>}
function download(name:string,text:string,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const krNotes:Record<string,string>={'08':'서울 환영 만찬. 드래곤힐 로지는 숙박 후보이며 예약은 미확정입니다.','09':'춘천 도심을 지나 신매대교 인증센터까지 방문한 뒤 역으로 이동하세요. 서울 구간 인증센터는 출발지와 강변 선택에 따라 달라집니다.','10':'해맞이공원에서 첫 도장을 받으세요. 울진군은 넓으므로 숙소 위치 확정 후 60km 예상 거리와 일별 인증센터를 확인해야 합니다.','11':'임원과 한재공원을 거쳐 북쪽으로 이동합니다. 숙박 장소에 따라 일별 인증센터 배정이 달라질 수 있습니다.','12':'경포해변이 이번 여행의 마지막 해안 인증센터입니다. 차량 탑승 전 방문하세요. 양양과 강원 북부는 이번 일정에 포함되지 않습니다.','13':'캠프 험프리스 주변 라이딩 후 단체 만찬. 식사 장소와 필요한 출입 절차를 확인하세요.'};
const krTransfers:Record<string,string>={'08':'개별 도착 및 이동 계획 미정','09':'기차로 복귀 · 열차, 출발 시각, 자전거 탑승 조건 확인 필요','10':'라이딩 전 버스/차량으로 영덕 이동 · 적재 시각 미정','11':'지원 차량 및 픽업 계획 미정','12':'라이딩 후 버스/차량으로 캠프 험프리스 이동 · 픽업 시각 미정','13':'개별 출발 계획 미정'};
export default function Home(){
 const [ko,setKo]=useState(false),[tab,setTab]=useState('trip'),[trip,setTrip]=useState('oct26'),[dayId,setDayId]=useState('09');
 const [records,setRecords]=useState<RecordMap>({}),[loading,setLoading]=useState(true),[error,setError]=useState(''),[busy,setBusy]=useState(false),[rider,setRider]=useState(''),[modal,setModal]=useState(''),[form,setForm]=useState<RecordMap>({}),[filter,setFilter]=useState('all'),[weather,setWeather]=useState<any>(null),[wReload,setWReload]=useState(0);
 const [origin,setOrigin]=useState<number[]|null>(null),[originName,setOriginName]=useState(''),[found,setFound]=useState<CP[]>([]),[finding,setFinding]=useState(false),[findError,setFindError]=useState(''),[start,setStart]=useState('sunrise'),[destination,setDestination]=useState('sweetfish'),[near,setNear]=useState<any>(null),[range,setRange]=useState('200'),[printMode,setPrintMode]=useState(false),[transferFrom,setTransferFrom]=useState('부산'),[transferTo,setTransferTo]=useState('군산');
 const [shared,setShared]=useState<RecordMap>({}),[sharedStatus,setSharedStatus]=useState('loading');
 useEffect(()=>{let active=true;setShared(readShared(trip));const refreshShared=()=>pullShared(trip).then(v=>{if(active){setShared(v);setSharedStatus('connected');}}).catch(()=>{if(active)setSharedStatus('offline');});void refreshShared();const stop=watchShared(trip,()=>{if(active){setShared(readShared(trip));setSharedStatus('connected');}});const timer=setInterval(refreshShared,60000);window.addEventListener('online',refreshShared);return()=>{active=false;stop();clearInterval(timer);window.removeEventListener('online',refreshShared);};},[trip]);
 const discoverSeq=useRef(0),nearSeq=useRef(0);
 const t=(en:string,kr:string)=>ko?kr:en;
 const riders=Object.entries(records).filter(([k])=>k.startsWith('rider:')).map(([k,v])=>({id:k.slice(6),...v}));
 const trips=[{id:'oct26',name:t('October Korea Tour','10월 한국 자전거 여행')},...Object.entries(records).filter(([k])=>k.startsWith('trip:')).map(([k,v])=>({id:k.slice(5),...v}))];
 const days=[...(trip==='oct26'?seedDays:[]),...Object.entries(records).filter(([k,v])=>k.startsWith('ride:')&&v.trip===trip).map(([k,v])=>v as Day)].map(d=>({...d,title:shared[d.id]?.title||d.title,ko:shared[d.id]?.title||d.ko})).sort((a,b)=>a.date.localeCompare(b.date));
 const day=days.find(d=>d.id===dayId)||days[0];
 const allChecks:CP[]=[...seedChecks,...Object.entries(records).filter(([k])=>k.startsWith('checkpoint:')).map(([k,v])=>v as CP)];
 const known=allChecks.map(c=>({...c,...found.find(f=>f.id===c.id)}));
 const catalog=[...known,...found.filter(f=>!known.some(c=>c.id===f.id))];
 const dayData=records['day:'+day?.id]||{};
 const dayChecks=dayData.checkpointIds?dayData.checkpointIds.map((id:string)=>catalog.find(c=>c.id===id)).filter(Boolean):allChecks.filter(c=>c.day===day?.id);
 const chosenRider=riders.find(r=>r.id===rider);
 const stamped=(id:string)=>records[`stamp:${rider}:${id}`]?.collected;
 const count=allChecks.filter(c=>stamped(c.id)).length;
 const selectedTrip=trips.find(x=>x.id===trip);
 const refresh=useCallback(async()=>{setLoading(true);try{setRecords(readRecords());setError('');}catch(e:any){setError(e.message);}finally{setLoading(false);}},[]);
 useEffect(()=>{let pref=null;try{pref=localStorage.getItem('korea-ride-language');}catch{}setKo(pref?pref==='ko':navigator.language.startsWith('ko'));void refresh();},[refresh]);
 useEffect(()=>{if(!rider&&riders.length)setRider(riders[0].id);},[riders.length,rider]);
 useEffect(()=>{document.documentElement.lang=ko?'ko':'en';},[ko]);
