 useEffect(()=>{const ctx=(document as any).modelContext;if(!ctx?.registerTool)return;const c=new AbortController();try{Promise.resolve(ctx.registerTool({name:'get_korea_trip',description:'Read the currently selected trip and its ride days.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({trip:selectedTrip,days,checkpoints:allChecks})},{signal:c.signal})).catch(()=>{});}catch{}return()=>c.abort();},[trip,records,ko]);
 async function save(key:string,value:any){if(busy)return false;setBusy(true);try{setRecords(writeRecord(key,value));toast.success(t('Saved','저장되었습니다'));return true;}catch(e:any){toast.error(t(e.message,'저장하지 못했습니다. 입력 내용을 유지한 채 다시 시도하세요.'));return false;}finally{setBusy(false);}}
 function open(kind:string,values:RecordMap={}){setForm(values);setModal(kind);}
