 async function stamp(c:CP){if(!allChecks.some(x=>x.id===c.id)){toast.error(t('Save this checkpoint to the catalog first.','이 인증센터를 먼저 목록에 저장하세요.'));return;}if(!rider){open('rider');return;}await save(`stamp:${rider}:${c.id}`,{collected:!stamped(c.id),date:!stamped(c.id)?new Date().toISOString():null,trip});}
 async function discover(point:number[],name:string){const seq=++discoverSeq.current;setOrigin(point);setOriginName(name);setFinding(true);setFindError('');setFound([]);try{const j:any=await nearbyPlaces(point[0],point[1]);if(seq!==discoverSeq.current)return;setFound(j.results);if(!j.results.length)setFindError(t('No mapped stamp booths found. Use the catalog below.','지도에 등록된 인증센터를 찾지 못했습니다. 아래 목록을 이용하세요.'));}catch(e){setFindError(t('Live map search is unavailable. The checkpoint catalog still works.','실시간 지도 검색을 이용할 수 없습니다. 인증센터 목록은 이용 가능합니다.'));}finally{if(seq===discoverSeq.current)setFinding(false);}}
 function locate(){if(!navigator.geolocation){setFindError(t('Location is unavailable. Choose an area.','위치를 사용할 수 없습니다. 지역을 선택하세요.'));return;}setFinding(true);navigator.geolocation.getCurrentPosition(p=>{if(p.coords.latitude<33||p.coords.latitude>38.7||p.coords.longitude<124||p.coords.longitude>132){setFinding(false);setFindError(t('You are outside South Korea. Choose a Korean area to plan ahead.','현재 한국 밖에 있습니다. 한국 지역을 선택해 미리 계획하세요.'));return;}void discover([p.coords.latitude,p.coords.longitude],t('Your location','현재 위치'));},()=>{setFinding(false);setFindError(t('Location permission was not available. Choose an area instead.','위치 권한이 없습니다. 지역을 선택하세요.'));},{timeout:15000,maximumAge:60000});}
