 function stop(c:CP,i:number){return <article className="stop" key={c.id}><div className={'stop-number '+(stamped(c.id)?'done':'')}>{stamped(c.id)?<Check size={18}/>:String(i+1).padStart(2,'0')}</div><div className="stop-body"><div className="row"><div><h3>{ko?c.ko:c.name}</h3><p className="muted">{ko?c.name:c.ko}</p></div><button className={'stamp-button '+(stamped(c.id)?'collected':'')} disabled={busy||loading||!!error} onClick={()=>stamp(c)}><Stamp size={16}/>{stamped(c.id)?t('Collected','수집 완료'):t('Stamp','도장 기록')}</button></div><div className="row stop-meta"><span>{c.route==='Unassigned'?t('Map listing · verify stamp booth','지도 정보 · 인증센터 여부 확인 필요'):c.route}</span><a href={naver(c.ko+' 인증센터')} target="_blank" rel="noreferrer">{t('Open in Naver','네이버 지도')} <ArrowUpRight size={14}/></a></div>{services(c)}</div></article>}
 function exportPassport(){const rows=allChecks.filter(c=>filter==='all'||c.route===filter).map(c=>({route:c.route,checkpoint:c.name,korean:c.ko,collected:!!stamped(c.id),date:records[`stamp:${rider}:${c.id}`]?.date||''}));const csv='\ufeff'+[ ['Rider / 라이더',chosenRider?.name||''],['Personal trip record / 개인 여행 기록'],['Route / 노선','Checkpoint / 인증센터','Korean / 한국어','Collected / 수집','Date / 날짜'],...rows.map(r=>[r.route,r.checkpoint,r.korean,r.collected?'Yes':'',r.date])].map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');download('korea-cycling-passport.csv',csv,'text/csv;charset=utf-8');}
